   713  static inline void
   714  hb_ot_position_complex (hb_ot_shape_context_t *c)
   715  {
   716    unsigned int count = c->buffer->len;
   717    hb_glyph_info_t *info = c->buffer->info;
   718    hb_glyph_position_t *pos = c->buffer->pos;
   719
   720    /* If the font has no GPOS, AND, no fallback positioning will
   721     * happen, AND, direction is forward, then when zeroing mark
   722     * widths, we shift the mark with it, such that the mark
   723     * is positioned hanging over the previous glyph.  When
   724     * direction is backward we don't shift and it will end up
   725     * hanging over the next glyph after the final reordering.
   726     * If fallback positinoing happens or GPOS is present, we don't
   727     * care.
   728     */
   729    bool adjust_offsets_when_zeroing = c->fallback_positioning &&
   730                                       !c->plan->shaper->fallback_position &&
   731                                       HB_DIRECTION_IS_FORWARD (c->buffer->props.direction);
   732
   733    /* We change glyph origin to what GPOS expects (horizontal), apply GPOS, change it back. */
   734
   735    /* The nil glyph_h_origin() func returns 0, so no need to apply it. */
   736    if (c->font->has_glyph_h_origin_func ())
   737      for (unsigned int i = 0; i < count; i++)
   738        c->font->add_glyph_h_origin (info[i].codepoint,
   739                                     &pos[i].x_offset,
   740                                     &pos[i].y_offset);
   741
   742    hb_ot_layout_position_start (c->font, c->buffer);
   743
   744    switch (c->plan->shaper->zero_width_marks)
   745    {
   746      case HB_OT_SHAPE_ZERO_WIDTH_MARKS_BY_GDEF_EARLY:
   747        zero_mark_widths_by_gdef (c->buffer, adjust_offsets_when_zeroing);
   748        break;
   749
   750      default:
   751      case HB_OT_SHAPE_ZERO_WIDTH_MARKS_NONE:
   752      case HB_OT_SHAPE_ZERO_WIDTH_MARKS_BY_GDEF_LATE:
   753        break;
   754    }
   755
   756    if (likely (!c->fallback_positioning))
   757      c->plan->position (c->font, c->buffer);
   758
   759    switch (c->plan->shaper->zero_width_marks)
   760    {
   761      case HB_OT_SHAPE_ZERO_WIDTH_MARKS_BY_GDEF_LATE:
   762        zero_mark_widths_by_gdef (c->buffer, adjust_offsets_when_zeroing);
   763        break;
   764
   765      default:
   766      case HB_OT_SHAPE_ZERO_WIDTH_MARKS_NONE:
   767      case HB_OT_SHAPE_ZERO_WIDTH_MARKS_BY_GDEF_EARLY:
   768        break;
   769    }
   770
   771    /* Finishing off GPOS has to follow a certain order. */
   772    hb_ot_layout_position_finish_advances (c->font, c->buffer);
   773    hb_ot_zero_width_default_ignorables (c);
   774    hb_ot_layout_position_finish_offsets (c->font, c->buffer);
   775
   776    /* The nil glyph_h_origin() func returns 0, so no need to apply it. */
   777    if (c->font->has_glyph_h_origin_func ())
   778      for (unsigned int i = 0; i < count; i++)
   779        c->font->subtract_glyph_h_origin (info[i].codepoint,
   780                                          &pos[i].x_offset,
   781                                          &pos[i].y_offset);
   782  }
